import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function HomePage() {
  const [availableSlots, setAvailableSlots] = useState(1000);
  const navigate = useNavigate();

  const handleBookNow = () => {
    if (availableSlots > 0) {
      navigate("/booking");
    } else {
      alert("No slots available!");
    }
  };

  return (
    <div style={styles.page}>
      {/* Navbar */}
      <div style={styles.navbar}>
        <h2 style={{ margin: 0 }}>Parking Slot System</h2>
      </div>

      <div style={styles.mainContent}>
        {/* Sidebar */}
        <div style={styles.sidebar}>
          <button style={styles.sidebarBtn} onClick={() => navigate("/")}>
            Dashboard
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/booking")}>
            Booking
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/payment")}>
            Payment
          </button>
          <button style={styles.sidebarBtn} onClick={() => navigate("/success")}>
            Success
          </button>
        </div>

        {/* Content Area */}
        <div style={styles.content}>
          <h1>Parking Slot Dashboard</h1>
          <h2>Available Slots: {availableSlots}</h2>
          <button style={styles.button} onClick={handleBookNow}>
            Book Now
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: { display: "flex", flexDirection: "column", height: "100vh" },
  navbar: {
    background: "#333",
    color: "#fff",
    padding: "15px 20px",
    fontSize: "20px"
  },
  mainContent: { display: "flex", flex: 1 },
  sidebar: {
    width: "200px",
    background: "#f4f4f4",
    padding: "20px",
    display: "flex",
    flexDirection: "column",
    gap: "10px"
  },
  sidebarBtn: {
    padding: "10px",
    border: "none",
    background: "#ddd",
    cursor: "pointer",
    fontSize: "16px",
    textAlign: "left"
  },
  content: { flex: 1, padding: "20px", textAlign: "center" },
  button: { padding: "10px 20px", fontSize: "18px", cursor: "pointer" }
};

export default HomePage;
